var pgErrorMessages = [...]struct {
	state int
	token int
	msg   string
}{}

//line yaccpar:1

/*	parser for yacc output	*/

var (
	pgDebug        = 0
	pgErrorVerbose = false
)

type pgLexer interface {
	Lex(lval *pgSymType) int
	Error(s string)
}

type pgParser interface {
	Parse(pgLexer) int
	Lookahead() int
}

type pgParserImpl struct {
	lval  pgSymType
	stack [pgInitialStackSize]pgSymType
	char  int
}

func (p *pgParserImpl) Lookahead() int {
	return p.char
}

func pgNewParser() pgParser {
	return &pgParserImpl{}
}

const pgFlag = -1000

func pgTokname(c int) string {
	if c >= 1 && c-1 < len(pgToknames) {
		if pgToknames[c-1] != "" {
			return pgToknames[c-1]
		}
	}
	return __yyfmt__.Sprintf("tok-%v", c)
}

func pgStatname(s int) string {
	if s >= 0 && s < len(pgStatenames) {
		if pgStatenames[s] != "" {
			return pgStatenames[s]
		}
	}
	return __yyfmt__.Sprintf("state-%v", s)
}

func pgErrorMessage(state, lookAhead int) string {
	const TOKSTART = 4

	if !pgErrorVerbose {
		return "syntax error"
	}

	for _, e := range pgErrorMessages {
		if e.state == state && e.token == lookAhead {
			return "syntax error: " + e.msg
		}
	}

	res := "syntax error: unexpected " + pgTokname(lookAhead)

	// To match Bison, suggest at most four expected tokens.
	expected := make([]int, 0, 4)

	// Look for shiftable tokens.
	base := int(pgPact[state])
	for tok := TOKSTART; tok-1 < len(pgToknames); tok++ {
		if n := base + tok; n >= 0 && n < pgLast && int(pgChk[int(pgAct[n])]) == tok {
			if len(expected) == cap(expected) {
				return res
			}
			expected = append(expected, tok)
		}
	}

	if pgDef[state] == -2 {
		i := 0
		for pgExca[i] != -1 || int(pgExca[i+1]) != state {
			i += 2
		}

		// Look for tokens that we accept or reduce.
		for i += 2; pgExca[i] >= 0; i += 2 {
			tok := int(pgExca[i])
			if tok < TOKSTART || pgExca[i+1] == 0 {
				continue
			}
			if len(expected) == cap(expected) {
				return res
			}
			expected = append(expected, tok)
		}

		// If the default action is to accept or reduce, give up.
		if pgExca[i+1] != 0 {
			return res
		}
	}

	for i, tok := range expected {
		if i == 0 {
			res += ", expecting "
		} else {
			res += " or "
		}
		res += pgTokname(tok)
	}
	return res
}

